import Box from "@mui/material/Box";
const styles = { color: "primary.main" } as const;
export function Subject() { return <Box sx={styles} />; }

import Box from "@mui/material/Box";
const base = { color: "primary.main" } as const;
export function Subject() { return <Box sx={{ ...base, p: 2 }} />; }

import Box from "@mui/material/Box";
const styles = { color: "#f00" } as const;
export function Subject() { return <Box sx={styles} />; }

import Box from "@mui/material/Box";
const base = { color: "#f00" } as const;
export function Subject() { return <Box sx={{ ...base, p: 2 }} />; }

import Box from "@mui/material/Box";
declare const external: any;
export function Subject() { return <Box sx={{ ...external }} />; }

import Box from "@mui/material/Box";
declare const external: any;
export function Subject() { return <Box sx={external} />; }

import Box from "@mui/material/Box";
const styles = { color: "primary.main" }; styles.color = "#f00";
export function Subject() { return <Box sx={styles} />; }

import Box from "@mui/material/Box";
let styles = { color: "primary.main" }; styles = { color: "#f00" };
export function Subject() { return <Box sx={styles} />; }

import Button from "@mui/material/Button";
function Wrapper(props: any) { return <Button {...props} />; }
export function Subject() { return <Wrapper sx={{ p: 2 }} />; }

import Box from "@mui/material/Box";
declare const colors: Record<string, string>; declare const tone: string;
export function Subject() { return <Box sx={{ color: colors[tone] }} />; }

import Box from "@mui/material/Box";
declare const on: boolean;
export function Subject() { return <Box sx={on ? { color: "primary.main" } : { color: "#f00" }} />; }
